-- SOOrder compliance hold fields (from AesthetikERP consolidation)
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHold')
  ALTER TABLE SOOrder ADD UsrComplianceHold bit NULL;
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHoldReason')
  ALTER TABLE SOOrder ADD UsrComplianceHoldReason nvarchar(500) NULL;
-- SOOrder HubSpot + WMS fields
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrHubSpotDealId')
  ALTER TABLE SOOrder ADD UsrHubSpotDealId nvarchar(50) NULL;
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrWMSStatus')
  ALTER TABLE SOOrder ADD UsrWMSStatus nvarchar(20) NULL;
-- BAccount pay link disable field
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('BAccount') AND name = 'UsrDisablePayLink')
  ALTER TABLE BAccount ADD UsrDisablePayLink bit NULL;

Graph.CDATA:
using PX.Data;

namespace HeritageFabrics.SO
{
    public class SOShipmentLabelExt : PXCacheExtension<PX.Objects.SO.SOShipment>
    {
        public static bool IsActive() => false;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using PX.Data;
using PX.Data.BQL;
using PX.Data.BQL.Fluent;
using PX.Objects.IN;
using PX.Objects.SO;

namespace HeritageFabrics.SO
{
    /// <summary>
    /// Auto-allocation for piece goods (PIECENBR lot class) on PC/FO orders.
    ///
    /// Fires on RowUpdated when InventoryID + SiteID are populated:
    ///   1. For each unallocated PIECENBR line, find best bolt >= line qty
    ///   2. If no single bolt covers it, split across multiple lines (120% overship cap)
    ///   3. Remainder → backorder line with POCreate = true
    ///   4. Sorting: FIFO (oldest receipt), then largest bolt (fewer lines)
    ///   5. Each line gets full bolt qty (whole bolt allocation)
    ///
    /// PC/FO orders are full-bolt by nature — qty override to actual bolt
    /// yardage is the correct behavior.
    /// </summary>
    public class SOOrderEntry_AutoAllocation : PXGraphExtension<SOOrderEntry>
    {
        public static bool IsActive() => true;

        private const string PieceGoodsClassID = "PIECENBR";
        private const decimal OvershipFactor = 1.20m;

        #region RowUpdated — auto-fire on line change

        protected void _(Events.RowUpdated<SOLine> e)
        {
            SOLine line = e.Row;
            SOLine oldLine = e.OldRow;
            if (line == null) return;

            // Only fire when InventoryID or SiteID changed
            if (line.InventoryID == oldLine?.InventoryID
                && line.SiteID == oldLine?.SiteID)
                return;

            // Gate: need both InventoryID and SiteID
            if (line.InventoryID == null) return;

            SOOrder order = Base.Document.Current;
            if (order == null) return;

            int? siteID = line.SiteID ?? order.DefaultSiteID;
            if (siteID == null) return;

            // PC/FO orders only
            string orderType = order.OrderType;
            if (orderType != "PC" && orderType != "FO") return;

            // Already has a lot assigned — don't override manual selection
            if (!string.IsNullOrEmpty(line.LotSerialNbr)) return;

            // Must be a PIECENBR item
            if (!IsPieceGoodsItem(line.InventoryID)) return;

            // Collect already-assigned serials on this order
            var assignedSerials = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (SOLine existing in Base.Transactions.Select())
            {
                if (existing.LineNbr == line.LineNbr) continue;
                if (!string.IsNullOrEmpty(existing.LotSerialNbr))
                    assignedSerials.Add(existing.LotSerialNbr);
            }

            int inventoryID = line.InventoryID.Value;
            decimal requestedQty = line.OrderQty ?? 0;
            decimal maxQty = requestedQty * OvershipFactor;
            string uom = line.UOM;

            // Get available bolts
            var bolts = GetAvailableBolts(inventoryID, siteID.Value, assignedSerials);

            if (bolts.Count == 0)
            {
                // No bolts — mark for PO
                Base.Transactions.Cache.SetValueExt<SOLine.pOCreate>(line, true);
                Base.Transactions.Update(line);
                PXTrace.WriteInformation(
                    $"[AUTO-ALLOC] Ln{line.LineNbr}: no bolts — marked for PO");

                UpdateOrderDescription(order, assignedSerials, line, null, true);
                return;
            }

            // Try single bolt first (tightest fit within overship cap)
            var singleBolt = bolts
                .Where(b => b.QtyOnHand >= requestedQty && b.QtyOnHand <= maxQty)
                .OrderBy(b => b.ReceiptDate ?? DateTime.MaxValue)
                .ThenByDescending(b => b.QtyOnHand)
                .FirstOrDefault();

            if (singleBolt != null)
            {
                Base.Transactions.Cache.SetValueExt<SOLine.lotSerialNbr>(line, singleBolt.LotSerialNbr);
                Base.Transactions.Cache.SetValueExt<SOLine.orderQty>(line, singleBolt.QtyOnHand);
                Base.Transactions.Update(line);
                assignedSerials.Add(singleBolt.LotSerialNbr);

                PXTrace.WriteInformation(
                    $"[AUTO-ALLOC] Ln{line.LineNbr}: single bolt {singleBolt.LotSerialNbr} " +
                    $"qty={singleBolt.QtyOnHand}");

                UpdateOrderDescription(order, assignedSerials, line, singleBolt.LotSerialNbr, false);
                return;
            }

            // Multi-bolt: split across lines
            var sorted = SortBolts(bolts);
            decimal totalAllocated = 0m;
            bool firstBolt = true;
            var allocatedLots = new List<string>();

            foreach (var bolt in sorted)
            {
                if (totalAllocated >= requestedQty) break;
                if (assignedSerials.Contains(bolt.LotSerialNbr)) continue;

                // Overship cap check — find a bolt that fits
                if (totalAllocated + bolt.QtyOnHand > maxQty)
                {
                    var fit = sorted.FirstOrDefault(b =>
                        !assignedSerials.Contains(b.LotSerialNbr) &&
                        b.QtyOnHand <= (maxQty - totalAllocated) &&
                        b.QtyOnHand > 0);
                    if (fit == null) break;
                    bolt.LotSerialNbr = fit.LotSerialNbr;
                    bolt.QtyOnHand = fit.QtyOnHand;
                    bolt.ReceiptDate = fit.ReceiptDate;
                }

                if (firstBolt)
                {
                    // Assign to the triggering line
                    Base.Transactions.Cache.SetValueExt<SOLine.lotSerialNbr>(line, bolt.LotSerialNbr);
                    Base.Transactions.Cache.SetValueExt<SOLine.orderQty>(line, bolt.QtyOnHand);
                    Base.Transactions.Update(line);
                    firstBolt = false;
                }
                else
                {
                    // Insert new line for additional bolt
                    SOLine newLine = Base.Transactions.Insert(new SOLine());
                    if (newLine == null) break;

                    Base.Transactions.Cache.SetValueExt<SOLine.inventoryID>(newLine, inventoryID);
                    Base.Transactions.Cache.SetValueExt<SOLine.siteID>(newLine, siteID);
                    if (uom != null)
                        Base.Transactions.Cache.SetValueExt<SOLine.uOM>(newLine, uom);
                    Base.Transactions.Cache.SetValueExt<SOLine.lotSerialNbr>(newLine, bolt.LotSerialNbr);
                    Base.Transactions.Cache.SetValueExt<SOLine.orderQty>(newLine, bolt.QtyOnHand);
                    Base.Transactions.Update(newLine);
                }

                totalAllocated += bolt.QtyOnHand;
                assignedSerials.Add(bolt.LotSerialNbr);
                allocatedLots.Add(bolt.LotSerialNbr);

                PXTrace.WriteInformation(
                    $"[AUTO-ALLOC] {(firstBolt ? "Ln" + line.LineNbr : "New line")}: " +
                    $"{bolt.LotSerialNbr} qty={bolt.QtyOnHand} " +
                    $"(total={totalAllocated}/{requestedQty})");
            }

            // Backorder remainder
            if (totalAllocated < requestedQty)
            {
                decimal remainder = requestedQty - totalAllocated;
                SOLine boLine = Base.Transactions.Insert(new SOLine());
                if (boLine != null)
                {
                    Base.Transactions.Cache.SetValueExt<SOLine.inventoryID>(boLine, inventoryID);
                    Base.Transactions.Cache.SetValueExt<SOLine.siteID>(boLine, siteID);
                    if (uom != null)
                        Base.Transactions.Cache.SetValueExt<SOLine.uOM>(boLine, uom);
                    Base.Transactions.Cache.SetValueExt<SOLine.orderQty>(boLine, remainder);
                    Base.Transactions.Cache.SetValueExt<SOLine.pOCreate>(boLine, true);
                    Base.Transactions.Update(boLine);

                    PXTrace.WriteInformation(
                        $"[AUTO-ALLOC] Backorder: qty={remainder} POCreate=true");
                }
            }

            UpdateOrderDescription(order, assignedSerials, line, null, false);
        }

        #endregion

        #region Helpers

        private void UpdateOrderDescription(SOOrder order, HashSet<string> allSerials,
            SOLine triggerLine, string singleLot, bool noBolts)
        {
            // Build description stamp
            string stamp;
            if (noBolts)
                stamp = $"[AUTO-ALLOC] No bolts for Ln{triggerLine.LineNbr} — PO created";
            else if (singleLot != null)
                stamp = $"[AUTO-ALLOC] Ln{triggerLine.LineNbr}: {singleLot}";
            else
                stamp = $"[AUTO-ALLOC ACTIVE] {allSerials.Count} bolt(s) assigned";

            string desc = order.OrderDesc ?? "";
            if (!desc.Contains("[AUTO-ALLOC"))
                desc = string.IsNullOrEmpty(desc) ? stamp : desc + " | " + stamp;
            else
                desc = stamp; // Replace previous stamp

            Base.Document.Cache.SetValueExt<SOOrder.orderDesc>(order, desc);
            Base.Document.Update(order);
        }

        private List<BoltCandidate> GetAvailableBolts(
            int inventoryID, int siteID, HashSet<string> assignedSerials)
        {
            var candidates = new List<BoltCandidate>();

            foreach (PXResult<INLotSerialStatus> row in SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.siteID.IsEqual<@P.AsInt>>>
                .View.ReadOnly.Select(Base, inventoryID, siteID))
            {
                var status = (INLotSerialStatus)row;
                if (status.LotSerialNbr == null) continue;
                if (assignedSerials.Contains(status.LotSerialNbr)) continue;

                decimal qtyOnHand = status.QtyOnHand ?? 0;
                decimal qtyAvail = status.QtyAvail ?? 0;

                if (qtyOnHand <= 0) continue;
                if (qtyAvail != qtyOnHand) continue; // Skip partially allocated bolts

                candidates.Add(new BoltCandidate
                {
                    LotSerialNbr = status.LotSerialNbr,
                    QtyOnHand = qtyOnHand,
                    ReceiptDate = status.ReceiptDate,
                });
            }

            return candidates;
        }

        private List<BoltCandidate> SortBolts(List<BoltCandidate> candidates)
        {
            // FIFO (oldest receipt) then largest bolt first (fewer lines)
            return candidates
                .OrderBy(c => c.ReceiptDate ?? DateTime.MaxValue)
                .ThenByDescending(c => c.QtyOnHand)
                .ToList();
        }

        private bool IsPieceGoodsItem(int? inventoryID)
        {
            if (inventoryID == null) return false;
            var item = SelectFrom<InventoryItem>
                .Where<InventoryItem.inventoryID.IsEqual<@P.AsInt>>
                .View.ReadOnly.Select(Base, inventoryID);
            if (item == null) return false;
            return string.Equals(
                ((InventoryItem)item).LotSerClassID,
                PieceGoodsClassID,
                StringComparison.OrdinalIgnoreCase);
        }

        private class BoltCandidate
        {
            public string LotSerialNbr { get; set; }
            public decimal QtyOnHand { get; set; }
            public DateTime? ReceiptDate { get; set; }
        }

        #endregion
    }
}

CustomizationPlugin.CDATA:
using System;
using System.Configuration;
using System.Data.SqlClient;
using PX.Data;

namespace Aesthetik.WMS
{
    public class InventoryQuantityDetailKBSetup : CustomizationPlugin
    {
        private const string GI_NAME = "InventoryQuantityDetail_KB";

        public override void UpdateDatabase()
        {
            WriteLog("Starting GI creation: " + GI_NAME);
            var connStr = this.GetConnectionString();
            using (var conn = new SqlConnection(connStr))
            {
                conn.Open();
                int companyId = GetCompanyId(conn);
                WriteLog("CompanyID: " + companyId);

                string designId = FindExistingGI(conn, companyId);
                if (designId != null)
                {
                    WriteLog("Found existing GI, clearing child rows: " + designId);
                    ClearChildRows(conn, designId, companyId);
                }
                else
                {
                    designId = Guid.NewGuid().ToString();
                    WriteLog("Creating new GI with DesignID: " + designId);
                    CreateGIDesign(conn, designId, companyId);
                }

                CreateTables(conn, designId, companyId);
                CreateRelations(conn, designId, companyId);
                CreateOnConditions(conn, designId, companyId);
                CreateResults(conn, designId, companyId);
                CreateWhereConditions(conn, designId, companyId);
                CreateSort(conn, designId, companyId);

                WriteLog("GI creation complete: " + GI_NAME);
                conn.Close();
            }
        }

        private string GetConnectionString()
        {
            return ConfigurationManager.ConnectionStrings["ProjectX"].ConnectionString;
        }

        private int GetCompanyId(SqlConnection conn)
        {
            using (var cmd = new SqlCommand("SELECT TOP 1 CompanyID FROM GIDesign WHERE CompanyID > 0 ORDER BY CompanyID", conn))
            {
                var r = cmd.ExecuteScalar();
                return r != null ? (int)r : 2;
            }
        }

        private string FindExistingGI(SqlConnection conn, int companyId)
        {
            using (var cmd = new SqlCommand("SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIDesign WHERE Name = @name AND CompanyID = @cid", conn))
            {
                cmd.Parameters.AddWithValue("@name", GI_NAME);
                cmd.Parameters.AddWithValue("@cid", companyId);
                var r = cmd.ExecuteScalar();
                return (r != null && r != DBNull.Value) ? r.ToString() : null;
            }
        }

        private void ClearChildRows(SqlConnection conn, string designId, int companyId)
        {
            string[] tables = { "GIResult", "GIWhere", "GISort", "GIOn", "GIRelation", "GITable", "GIFilter", "GIGroupBy", "GINavigationCondition", "GINavigationParameter", "GINavigationScreen" };
            foreach (var t in tables)
            {
                ExecNonQuery(conn, "DELETE FROM " + t + " WHERE DesignID = @did AND CompanyID = @cid", designId, companyId);
            }
        }

        private void CreateGIDesign(SqlConnection conn, string designId, int companyId)
        {
            ExecNonQuery(conn, @"
INSERT INTO GIDesign (CompanyID, DesignID, Name, FilterColCount, PageSize, ExportTop,
    NewRecordCreationEnabled, MassDeleteEnabled, AutoConfirmDelete, MassRecordsUpdateEnabled,
    MassActionsOnRecordsEnabled, ExposeViaOData, ExposeViaMobile, NoteID, RowID)
VALUES (@cid, @did, @name, 3, 0, 0, 0, 0, 0, 0, 0, 0, 0, NEWID(), NEWID())",
                designId, companyId, new SqlParameter("@name", GI_NAME));
        }

        private void CreateTables(SqlConnection conn, string designId, int companyId)
        {
            // Table aliases and full DAC names
            string[][] tables = {
                new[] { "InventoryItem",       "PX.Objects.IN.InventoryItem" },
                new[] { "INSiteStatus",        "PX.Objects.IN.INSiteStatus" },
                new[] { "TemplateItem",        "PX.Objects.IN.InventoryItem" },
                new[] { "POVendorInventory",   "PX.Objects.PO.POVendorInventory" },
                new[] { "WMSTLVendorLeadTimes","WMSTLVendorLeadTimes" },
                new[] { "POLine",              "PX.Objects.PO.POLine" },
                new[] { "POOrder",             "PX.Objects.PO.POOrder" },
            };
            foreach (var t in tables)
            {
                ExecNonQuery(conn, @"
INSERT INTO GITable (CompanyID, DesignID, Alias, Name, IsActive, NoteID, RowID)
VALUES (@cid, @did, @alias, @dacname, 1, NEWID(), NEWID())",
                    designId, companyId,
                    new SqlParameter("@alias", t[0]),
                    new SqlParameter("@dacname", t[1]));
            }
        }

        private void CreateRelations(SqlConnection conn, string designId, int companyId)
        {
            // All joins are from InventoryItem as parent, Left join
            // LineNbr, ParentTable (alias), ChildTable (alias), JoinType
            string[][] rels = {
                new[] { "1", "InventoryItem", "INSiteStatus",        "L" },
                new[] { "2", "InventoryItem", "TemplateItem",        "L" },
                new[] { "3", "InventoryItem", "POVendorInventory",   "L" },
                new[] { "4", "InventoryItem", "WMSTLVendorLeadTimes","L" },
                new[] { "5", "InventoryItem", "POLine",              "L" },
                new[] { "6", "POLine",        "POOrder",             "L" },
            };
            foreach (var r in rels)
            {
                ExecNonQuery(conn, @"
INSERT INTO GIRelation (CompanyID, DesignID, LineNbr, ParentTable, ChildTable, IsActive, JoinType, NoteID, RowID)
VALUES (@cid, @did, @lineNbr, @parent, @child, 1, @joinType, NEWID(), NEWID())",
                    designId, companyId,
                    new SqlParameter("@lineNbr", int.Parse(r[0])),
                    new SqlParameter("@parent", r[1]),
                    new SqlParameter("@child", r[2]),
                    new SqlParameter("@joinType", r[3]));
            }
        }

        private void CreateOnConditions(SqlConnection conn, string designId, int companyId)
        {
            // DesignID, RelationLineNbr, OnLineNbr, ParentField, Condition, ChildField, Operation
            string[][] ons = {
                // Rel 1: InventoryItem.InventoryID = INSiteStatus.InventoryID
                new[] { "1", "1", "InventoryID", "E ", "InventoryID", "A" },
                // Rel 2: InventoryItem.TemplateItemID = TemplateItem.InventoryID
                new[] { "2", "1", "TemplateItemID", "E ", "InventoryID", "A" },
                // Rel 3: InventoryItem.InventoryID = POVendorInventory.InventoryID
                new[] { "3", "1", "InventoryID", "E ", "InventoryID", "A" },
                // Rel 4: InventoryItem.InventoryID = WMSTLVendorLeadTimes.InventoryID
                new[] { "4", "1", "InventoryID", "E ", "InventoryID", "A" },
                // Rel 5: InventoryItem.InventoryID = POLine.InventoryID
                new[] { "5", "1", "InventoryID", "E ", "InventoryID", "A" },
                // Rel 6: POLine.OrderType = POOrder.OrderType AND POLine.OrderNbr = POOrder.OrderNbr
                new[] { "6", "1", "OrderType", "E ", "OrderType", "A" },
                new[] { "6", "2", "OrderNbr", "E ", "OrderNbr", "A" },
            };
            foreach (var o in ons)
            {
                ExecNonQuery(conn, @"
INSERT INTO GIOn (CompanyID, DesignID, LineNbr, OnLineNbr, ParentField, Condition, ChildField, Operation, NoteID, RowID)
VALUES (@cid, @did, @relLineNbr, @onLineNbr, @parentField, @condition, @childField, @operation, NEWID(), NEWID())",
                    designId, companyId,
                    new SqlParameter("@relLineNbr", int.Parse(o[0])),
                    new SqlParameter("@onLineNbr", int.Parse(o[1])),
                    new SqlParameter("@parentField", o[2]),
                    new SqlParameter("@condition", o[3]),
                    new SqlParameter("@childField", o[4]),
                    new SqlParameter("@operation", o[5]));
            }
        }

        private void CreateResults(SqlConnection conn, string designId, int companyId)
        {
            // LineNbr, SortOrder, ObjectName (alias), Field, Width, IsVisible, Caption
            string[][] cols = {
                new[] { "1",  "1",  "InventoryItem",       "InventoryCD",      "120", "1", "Inventory ID" },
                new[] { "2",  "2",  "InventoryItem",       "Descr",            "220", "1", "Pattern Color" },
                new[] { "3",  "3",  "TemplateItem",        "Descr",            "180", "1", "Pattern" },
                new[] { "4",  "4",  "POVendorInventory",   "VendorID",         "120", "1", "Vendor" },
                new[] { "5",  "5",  "InventoryItem",       "CountryOfOrigin",  "80",  "1", "CoO" },
                new[] { "6",  "6",  "InventoryItem",       "ItemStatus",       "80",  "1", "Item Status" },
                new[] { "7",  "7",  "INSiteStatus",        "QtyOnHand",        "100", "1", "Qty On Hand" },
                new[] { "8",  "8",  "INSiteStatus",        "QtyAvail",         "100", "1", "Qty Available" },
                new[] { "9",  "9",  "WMSTLVendorLeadTimes","LeadTimeDays",     "80",  "1", "Lead Time (Days)" },
                new[] { "10", "10", "POLine",              "OpenQty",          "80",  "1", "Open Qty on PO" },
                new[] { "11", "11", "POOrder",             "OrderNbr",         "100", "1", "PO Number" },
                new[] { "12", "12", "POLine",              "UsrExpArrivalDate","100", "1", "Expected Arrival" },
            };
            foreach (var c in cols)
            {
                ExecNonQuery(conn, @"
INSERT INTO GIResult (CompanyID, DesignID, LineNbr, SortOrder, IsActive, ObjectName, Field, Width, IsVisible,
    DefaultNav, QuickFilter, FastFilter, Caption, RowID, NoteID)
VALUES (@cid, @did, @lineNbr, @sortOrder, 1, @objectName, @field, @width, @isVisible,
    0, 0, 1, @caption, NEWID(), NEWID())",
                    designId, companyId,
                    new SqlParameter("@lineNbr", int.Parse(c[0])),
                    new SqlParameter("@sortOrder", int.Parse(c[1])),
                    new SqlParameter("@objectName", c[2]),
                    new SqlParameter("@field", c[3]),
                    new SqlParameter("@width", int.Parse(c[4])),
                    new SqlParameter("@isVisible", int.Parse(c[5])),
                    new SqlParameter("@caption", c[6]));
            }
            // Make Inventory ID the default navigation column
            ExecNonQuery(conn, @"UPDATE GIResult SET DefaultNav = 1 WHERE DesignID = @did AND CompanyID = @cid AND LineNbr = 1", designId, companyId);
        }

        private void CreateWhereConditions(SqlConnection conn, string designId, int companyId)
        {
            // WHERE conditions with OR NULL pattern for LEFT JOIN compatibility
            // LineNbr, OpenBrackets, CloseBrackets, DataFieldName, Condition, Value1, Operation
            string[][] wheres = {
                // (INSiteStatus.SiteID = '99' OR INSiteStatus.SiteID IS NULL)
                new[] { "1", "1", "0", "INSiteStatus.SiteID",          "E ", "99",   "O" },
                new[] { "2", "0", "1", "INSiteStatus.SiteID",          "NU", "",     "A" },
                // AND InventoryItem.StkItem = True
                new[] { "3", "0", "0", "InventoryItem.StkItem",        "E ", "True", "A" },
                // AND (POVendorInventory.IsDefault = True OR POVendorInventory.IsDefault IS NULL)
                new[] { "4", "1", "0", "POVendorInventory.IsDefault",  "E ", "True", "O" },
                new[] { "5", "0", "1", "POVendorInventory.IsDefault",  "NU", "",     "A" },
                // AND (POLine.OpenQty > 0 OR POLine.OpenQty IS NULL)
                new[] { "6", "1", "0", "POLine.OpenQty",               "G ", "0",    "O" },
                new[] { "7", "0", "1", "POLine.OpenQty",               "NU", "",     "A" },
                // AND (POOrder.Status = 'N' OR POOrder.Status = 'O' OR POOrder.Status IS NULL)
                new[] { "8",  "1", "0", "POOrder.Status",              "E ", "N",    "O" },
                new[] { "9",  "0", "0", "POOrder.Status",              "E ", "O",    "O" },
                new[] { "10", "0", "1", "POOrder.Status",              "NU", "",     "A" },
            };
            foreach (var w in wheres)
            {
                ExecNonQuery(conn, @"
INSERT INTO GIWhere (CompanyID, DesignID, LineNbr, OpenBrackets, CloseBrackets, IsActive, DataFieldName,
    Condition, IsExpression, Value1, Operation, NoteID, RowID)
VALUES (@cid, @did, @lineNbr, @openBr, @closeBr, 1, @dataField,
    @condition, 0, @value1, @operation, NEWID(), NEWID())",
                    designId, companyId,
                    new SqlParameter("@lineNbr", int.Parse(w[0])),
                    new SqlParameter("@openBr", int.Parse(w[1])),
                    new SqlParameter("@closeBr", int.Parse(w[2])),
                    new SqlParameter("@dataField", w[3]),
                    new SqlParameter("@condition", w[4]),
                    new SqlParameter("@value1", w[5]),
                    new SqlParameter("@operation", w[6]));
            }
        }

        private void CreateSort(SqlConnection conn, string designId, int companyId)
        {
            ExecNonQuery(conn, @"
INSERT INTO GISort (CompanyID, DesignID, LineNbr, IsActive, DataFieldName, SortOrder, NoteID, RowID)
VALUES (@cid, @did, 1, 1, 'InventoryItem.InventoryCD', 'A', NEWID(), NEWID())",
                designId, companyId);
        }

        // Helper: execute non-query with DesignID + CompanyID + optional extra params
        private void ExecNonQuery(SqlConnection conn, string sql, string designId, int companyId, params SqlParameter[] extraParams)
        {
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.AddWithValue("@did", designId);
                cmd.Parameters.AddWithValue("@cid", companyId);
                foreach (var p in extraParams)
                    cmd.Parameters.Add(p);
                cmd.ExecuteNonQuery();
            }
        }
    }
}
